import{_ as n,c as s,o as e,a2 as t}from"./chunks/framework.bjzS3PU6.js";const u=JSON.parse('{"title":"Staff Journals Series C (1997)","description":"","frontmatter":{},"headers":[],"relativePath":"lore/STAFF_JOURNALS_SERIES_C_1997_DECODED.md","filePath":"lore/STAFF_JOURNALS_SERIES_C_1997_DECODED.md"}'),i={name:"lore/STAFF_JOURNALS_SERIES_C_1997_DECODED.md"};function l(p,a,o,r,c,h){return e(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="staff-journals-series-c-1997" tabindex="-1">Staff Journals Series C (1997) <a class="header-anchor" href="#staff-journals-series-c-1997" aria-label="Permalink to &quot;Staff Journals Series C (1997)&quot;">​</a></h1><h2 id="context-analysis" tabindex="-1">Context &amp; Analysis <a class="header-anchor" href="#context-analysis" aria-label="Permalink to &quot;Context &amp; Analysis&quot;">​</a></h2><p><strong>Puzzle Origin:</strong> Episode 1, Loot Drop 1</p><p><strong>Key Revelations:</strong></p><ul><li>Staff members experiencing psychological effects from working at the facility</li><li>Anomalous phenomena: delayed reflections, distorted glass, shared dreams</li><li>Dr. Ravel expressing ethical concerns about the experiments</li><li>Physical changes in subjects that aren&#39;t captured by scientific measurements</li><li>Staff questioning the morality and purpose of the research</li></ul><hr><h2 id="recovered-document" tabindex="-1">Recovered Document <a class="header-anchor" href="#recovered-document" aria-label="Permalink to &quot;Recovered Document&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Recovered From: node05.sj-securelab.net</span></span>
<span class="line"><span>Status: Partial, reconstructed from local cache fragments</span></span>
<span class="line"><span>Clearance: Confidential, Internal Morale Archive</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[1997-03-02 | Ellard, J.]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The chamber hum is lower this week. New power routing, maybe. Everyone swears the tone shifted, but we cannot agree on whether it rose or fell.</span></span>
<span class="line"><span>R-021 sat through six cycles without complaint. When we pulled him out, his pupils stayed wide and empty for nearly a minute.</span></span>
<span class="line"><span>He said it was fine. He said the quiet felt like &quot;a sponge.&quot; Whatever that means.</span></span>
<span class="line"><span>I left that part out of the formal report.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[1997-04-14 | Ruan, S.]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>They replaced the glass in Chamber 3. The last pane warped outward at the corners as if it softened under pressure. Maintenance blamed thermal drift.</span></span>
<span class="line"><span>When the reflection bends, it looks like the subjects are smiling.</span></span>
<span class="line"><span>But on the cameras, none of them are.</span></span>
<span class="line"><span>[wOrMbAbY: smiling reflections in bent glass. no thank you.]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>I caught my own reflection doing it yesterday. My face, but the smile held way too long.</span></span>
<span class="line"><span>[X1U: i hate this file so much]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[1997-06-30 | Vale, D.]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>People keep describing the same dream. Empty corridors, strange vending machines, small houses in fields. The hall lights flicker while they have these dreams, but the diagnostics say nothing is off.</span></span>
<span class="line"><span>We started running EM sweeps in the dorms. Nothing unusual.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>I have to cover the mirrors with lab towels lately.</span></span>
<span class="line"><span>I cannot handle the delay. Seeing myself blink a minute too late is too much.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[1997-08-12 | Ravel, M.]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Kerr wants me to draft a statement for the ethics audit. He wants careful language. He wants the word &quot;intent&quot; used sparingly and safely.</span></span>
<span class="line"><span>But the subjects do not care about intent. We are showing them a nature they should not see and most of them do not like it.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>If I say that aloud, they will call it projection or stress or misguided empathy.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Science is still too young to admit what is happening here.</span></span>
<span class="line"><span>[Post_Modem: &quot;science is too young&quot; is such an ominous sentence]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[1997-10-04 | Lorne, E.]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>I cannot shake the feeling that we are hurting them more than we understand.</span></span>
<span class="line"><span>The subjects come back changed in ways the metrics do not catch. Their voices echo slightly, even in open air. Their shadows feel heavy almost.</span></span>
<span class="line"><span>One of them asked me if I could &quot;hear the room breathing.&quot;</span></span>
<span class="line"><span>[PR0XYANG3L: the room breathing. sorry what.]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>I told him no.</span></span>
<span class="line"><span>But I did. I heard something.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The official line calls this adaptation.</span></span>
<span class="line"><span>Privately, I think we are peeling back something they were never meant to see.</span></span>
<span class="line"><span>I do not know if this program protects anyone. I am starting to doubt the mission entirely.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>End of recovered content. Remaining entries corrupted (CRC mismatch).</span></span></code></pre></div><hr><h2 id="related-entries" tabindex="-1">Related Entries <a class="header-anchor" href="#related-entries" aria-label="Permalink to &quot;Related Entries&quot;">​</a></h2><ul><li><a href="./../entries/people/J-Ellard">J. Ellard</a></li><li><a href="./../entries/people/S-Ruan">S. Ruan</a></li><li><a href="./../entries/people/D-Vale">D. Vale</a></li><li><a href="./../entries/people/Dr-M-Ravel">Dr. M. Ravel</a></li><li><a href="./../entries/people/E-Lorne">E. Lorne</a></li><li><a href="./../entries/people/Dr-E-Kerr">Dr. E. Kerr</a></li><li><a href="./../entries/locations/Saint-Juniper-Research-Campus">Saint Juniper Research Campus</a></li><li><a href="./../entries/organizations/Miter-Corporation">Miter Corporation</a></li></ul><h2 id="community-notes" tabindex="-1">Community Notes <a class="header-anchor" href="#community-notes" aria-label="Permalink to &quot;Community Notes&quot;">​</a></h2><p><em>(To be added)</em></p>`,13)])])}const m=n(i,[["render",l]]);export{u as __pageData,m as default};
